static void require(bool ok,const char *message){if(!ok)throw std::runtime_error(message);}
static void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);}
static QByteArray read(const QString &path){QFile f(path);require(f.open(QIODevice::ReadOnly),"Scientific-file artifact unreadable");return f.readAll();}
static void write(const QString &path,const QByteArray &data){QFile f(path);require(f.open(QIODevice::WriteOnly)&&f.write(data)==data.size(),"Scientific-file artifact write failed");}
static QString hash(const QString &path){return QCryptographicHash::hash(read(path),QCryptographicHash::Sha256).toHex();}
static QJsonObject live(){QJsonObject values;for(const auto *key:{"LEAP_SECS_FILE","EOP_FILE","NUTATION_COEFF_FILE","LSK_FILE"})values.insert(key,QDir::cleanPath(QString::fromStdString(FileManager::Instance()->GetFullPathname(key))));values.insert("loaded_EOP",QDir::cleanPath(QString::fromStdString(GmatGlobal::Instance()->GetEopFile()->GetFileName())));values.insert("loaded_nutation",QDir::cleanPath(QString::fromStdString(GmatGlobal::Instance()->GetItrfCoefficientsFile()->GetNutationFileName())));values.insert("loaded_LSK",QDir::cleanPath(QString::fromStdString(Moderator::Instance()->GetSolarSystemInUse()->GetStringParameter("LSKFilename"))));return values;}
static QJsonArray offsets(){QJsonArray result;for(const auto pair:{std::pair<double,double>{21544.5,32.},std::pair<double,double>{27754.5,37.}}){const double tai=TimeSystemConverter::Instance()->Convert(pair.first,TimeSystemConverter::UTCMJD,TimeSystemConverter::TAIMJD,2430000.);const double seconds=(tai-pair.first)*86400;require(std::isfinite(seconds)&&std::abs(seconds-pair.second)<1e-5,"Known NASA UTC/TAI leap-second offset differs");result.append(QJsonObject{{"utc_mjd",pair.first},{"tai_mjd",tai},{"offset_seconds",seconds},{"expected_seconds",pair.second}});}return result;}
static QJsonArray values(const QByteArray &raw){const auto fields=QString::fromUtf8(raw).trimmed().split(',');require(fields.size()==8,"Scientific-file report cardinality differs");QJsonArray result;for(const auto &field:fields){bool ok=false;const double x=field.toDouble(&ok);require(ok&&std::isfinite(x),"Scientific-file report nonfinite");result.append(x);}require(result.last().toDouble()==41&&std::abs((result.first().toDouble()-21545)*86400-1)<1e-5,"Scientific-file epoch/sentinel differs");return result;}
